style.css:
body {
    background-image: url("https://i.ytimg.com/vi/narJzPZ1m38/hqdefault.jpg") !important;
    background-size: cover !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
    background-position: center center !important;
}

/* Optional: make background darker for style */
body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.35);
    pointer-events: none;
    z-index: -1;
}
